with remaining_keys as (select store_id, id from inventory except all select store_id, id from inventory where last_restock between '2023-09-01' and '2024-08-01'), reconciled as (select s.* from inventory s inner join remaining_keys k on s.store_id = k.store_id and s.id = k.id) select s.product_id, s.quantity, (select max(i2.quantity) from inventory i2 where i2.product_id = s.product_id) as max_inventory_quantity from reconciled s order by max_inventory_quantity desc nulls first
